-- SWORDASH(A!U)[X64]-V22.01
-- Do not edit this file. Any change breaks the decoder.
local _yurxtk = 75
local _vpnpro = 10
local _nnmgmi = 70
local _mmabym = ""

local _gopwej = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _cjslph(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _qbmecd(d)
	d = d:gsub("[^" .. _gopwej .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_gopwej:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ewghfu = _qbmecd(_mmabym)
local _yuavon = { _yurxtk, _vpnpro, _nnmgmi }
local _kbdbgj = {}
for i = 1, #_ewghfu do
	_kbdbgj[i] = string.char(_cjslph(_ewghfu:byte(i), _yuavon[(i - 1) % 3 + 1]))
end

local _grilnn = load or loadstring
local _stngvq, _tnoelh = _grilnn(table.concat(_kbdbgj), "=w")
if not _stngvq then
	gg.alert("Corrupted file: " .. tostring(_tnoelh))
	os.exit()
end
_stngvq()
